const enCatalog = { ...en, ...collectEn, ...collectPluralEn, ...pwaEn };
const frCatalog = { ...fr, ...collectFr, ...collectPluralFr, ...pwaFr };
const arCatalog = { ...ar, ...collectAr, ...collectPluralAr, ...pwaAr };

export type DonationCopyKey = keyof typeof enCatalog;

export function donationCopy(locale: AppLocale, key: DonationCopyKey, values?: Record<string, string | number>) {
  const template = (locale === 'fr' ? frCatalog[key] : locale === 'ar' ? arCatalog[key] : enCatalog[key]) ?? enCatalog[key];
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values?.[name] ?? `{${name}}`));
}
